export const LINT_RULES = [
  "hex-color",
  "arbitrary-tailwind",
  "glow-shadow",
  "gradient",
  "bad-radius",
] as const;

export type Rule = (typeof LINT_RULES)[number];

/** One Off_System_Value. `line` is 1-based. */
export interface Violation {
  file: string;
  line: number;
  rule: Rule;
}

/** Rules that do not apply to files generated by the Token_Generator (Requirement 3.3). */
export const GENERATED_FILE_EXEMPT_RULES: readonly Rule[] = [
  "hex-color",
  "glow-shadow",
  "bad-radius",
];
